import type {PropsWithChildren} from 'react'
import type {LayoutResponse} from '../types'
import {IsStafftoolsProvider} from '../contexts/IsStafftoolsProvider'

// Global providers are defined here and are passed via <Layout/>
export const AppProvider = ({children, ...props}: PropsWithChildren<LayoutResponse>) => {
  return <IsStafftoolsProvider isStafftools={props.isStafftools}>{children}</IsStafftoolsProvider>
}
