import {mainQuery} from '@github-ui/react-core/future/main-query'
import {branchProtectionsReadOnlyAppBuilder} from '../config/app-builder'
import type {IndexResponse} from '../types'

export const indexRoute = branchProtectionsReadOnlyAppBuilder.createQueryRouteConfig('indexRoute', {
  path: '/:owner/:repo/branch-protections',
  queries: [mainQuery<IndexResponse>()],
})

export const indexStafftoolsRoute = branchProtectionsReadOnlyAppBuilder.createQueryRouteConfig('indexStafftoolsRoute', {
  path: '/stafftools/repositories/:owner/:repo/branch-protections',
  queries: [mainQuery<IndexResponse>()],
})
