import {createContext, type PropsWithChildren, use, useMemo} from 'react'

const IsStafftoolsContext = createContext<boolean | null>(null)

export function IsStafftoolsProvider({children, isStafftools}: PropsWithChildren<{isStafftools?: boolean}>) {
  const value = useMemo(() => isStafftools ?? false, [isStafftools])
  return <IsStafftoolsContext value={value}>{children}</IsStafftoolsContext>
}

export const useIsStafftools = () => {
  const context = use(IsStafftoolsContext)
  if (context === null) {
    throw new Error('useIsStafftools must be used inside a IsStafftoolsProvider')
  }
  return context
}
