import {registerDataRouterApp} from '@github-ui/react-core/register-app'
import {branchProtectionsReadOnlyAppBuilder} from './config/app-builder'

import {layoutRoute} from './routes/layout-route'
import {Layout} from './routes/layout'
import {indexRoute, indexStafftoolsRoute} from './routes/index-route'
import {Index} from './routes/index'
import {showRoute, showStafftoolsRoute} from './routes/show-route'
import {Show} from './routes/show'

export const branchProtectionsReadOnlyApp = branchProtectionsReadOnlyAppBuilder.createDataRouterAppFromRoutes([
  layoutRoute.toRoute({
    Component: Layout,
    children: [
      indexRoute.toRoute({Component: Index}),
      showRoute.toRoute({Component: Show}),
      indexStafftoolsRoute.toRoute({Component: Index}),
      showStafftoolsRoute.toRoute({Component: Show}),
    ],
  }),
])
registerDataRouterApp(branchProtectionsReadOnlyApp)
